    result.m22 = m11 * m33 - m13 * m31;
    result.m23 = m13 * m21 - m11 * m23;
    result.m31 = m21 * m32 - m22 * m31;
    result.m32 = m12 * m31 - m11 * m32;
    result.m33 = m11 * m22 - m12 * m21;
